        tmp = tools_md.with_suffix(".md.tmp")
        tmp.write_text(new, encoding="utf-8")
        tmp.replace(tools_md)
        _log(f"bet: TOOLS.md block {'rendered' if enabled else 'removed'}")
    except OSError as e:
        _log(f"bet: TOOLS.md write failed: {e}")


