# Tipos que ESTE daemon procesa. `query_pending_commands` (v1.6.0+)
# filtra por estos, así no se lleva commands de otros daemons (cron.*,
# tasks.* viven en tnode-chat-sync). Sin este filtro, el handler genérico
# marcaba como `error: unknown_command_type` antes de que el daemon
# dueño tuviera chance de procesarlos.
_HANDLED_TYPES = tuple(sorted({*_HANDLERS, "set_rest_credential"}))


_LEONARDO_CREDENTIAL_OPEN = """
const { createDecipheriv, createHmac } = require("node:crypto");
const { readFileSync } = require("node:fs");
try {
  const { envelope, nodeSecret, nodeId, commandId } = JSON.parse(readFileSync(0, "utf8"));
  const purpose = "tnode:leonardo-rest-credential:v1";
  const iv = Buffer.from(envelope.iv, "base64");
  const tag = Buffer.from(envelope.tag, "base64");
  const ciphertext = Buffer.from(envelope.ciphertext, "base64");
  if (envelope.version !== 1 || iv.length !== 12 || tag.length !== 16 ||
      ciphertext.length < 1 || ciphertext.length > 512) process.exit(1);
  const key = createHmac("sha256", nodeSecret).update(purpose).digest();
  const opener = createDecipheriv("aes-256-gcm", key, iv);
  opener.setAAD(Buffer.from(JSON.stringify([purpose, nodeId, commandId])));
  opener.setAuthTag(tag);
  process.stdout.write(Buffer.concat([opener.update(ciphertext), opener.final()]));
} catch (_) {
  process.exitCode = 1;
}
"""


def _write_leonardo_rest_credential(key: str) -> None:
    directory = OPENCLAW_DIR / "credentials"
    directory.mkdir(mode=0o700, exist_ok=True)
    info = directory.lstat()
    if not stat.S_ISDIR(info.st_mode) or info.st_uid != os.getuid() or info.st_mode & 0o022:
        raise ValueError("Invalid credentials directory")
    target = directory / "leonardo-rest.json"
    try:
        current = target.lstat()
    except FileNotFoundError:
        pass
    else:
        if not stat.S_ISREG(current.st_mode) or current.st_uid != os.getuid():
            raise ValueError("Invalid credentials file")
    staged_path = None
    try:
        with tempfile.NamedTemporaryFile(mode="w", encoding="utf-8", dir=directory, delete=False) as staged:
            staged_path = Path(staged.name)
            os.fchmod(staged.fileno(), 0o600)
            json.dump({"apiKey": key}, staged)
            staged.flush()
            os.fsync(staged.fileno())
        os.replace(staged_path, target)
    finally:
        if staged_path is not None:
            staged_path.unlink(missing_ok=True)


def _handle_leonardo_rest_credential(token: dict, cmd: dict) -> dict:
    try:
        cfg = load_config()
        if cfg["nodeId"] != token["nodeId"]:
            raise ValueError("Node mismatch")
        opened = subprocess.run(
            ["node", "-e", _LEONARDO_CREDENTIAL_OPEN],
            input=json.dumps({
                "envelope": cmd["params"], "nodeSecret": cfg["nodeSecret"],
                "nodeId": token["nodeId"], "commandId": cmd["id"],
            }),
            text=True, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, timeout=10, check=True,
        )
        if not re.fullmatch(r"[!-~]{1,512}", opened.stdout):
            raise ValueError("Invalid REST credential")
    except (OSError, ValueError, KeyError, subprocess.SubprocessError):
        return {"status": "error", "result": {"error": "credential_unreadable"}}
    try:
        _write_leonardo_rest_credential(opened.stdout)
    except (OSError, ValueError):
        return {"status": "error", "result": {"error": "credential_write_failed"}}
    return {"status": "done", "result": {}}


def handle_command(token: dict, cmd: dict) -> dict:
    cmd_type = cmd.get("type") or ""
    params = cmd.get("params") or {}
    if cmd_type == "set_rest_credential":
        return _handle_leonardo_rest_credential(token, cmd)
    handler = _HANDLERS.get(cmd_type)
    if handler is None:
        return {
            "status": "error",
            "result": {"error": f"unknown_command_type: {cmd_type}"},
        }
    return handler(token, params)


# ── Main loop ──────────────────────────────────────────────────

# ── Cron declarativo del resurtido (v1.41.0) ─────────────────────
# La CF syncInventoryFlowOnWrite (inventory_flow.ts) compone
# inventoryCronJson/inventoryCronHash en el node doc cuando el dueño toca
# config/inventoryFlow; aquí lo materializamos con el CLI del core (mismo
# patrón declarativo por hash que TOOLS.md). El motor del flujo es 100%
# agente (cron nativo OpenClaw, sesión aislada); este daemon SOLO garantiza
# que el job exista/desaparezca según lo declarado — no orquesta nada.
_INVENTORY_CRON_HASH_PATH = OPENCLAW_DIR / ".tnode-inventory-cron-hash"


def _read_inventory_cron_hash() -> str:
    try:
        return _INVENTORY_CRON_HASH_PATH.read_text(encoding="utf-8").strip()
    except OSError:
        return ""


def _write_inventory_cron_hash(value: str) -> None:
    try:
        _INVENTORY_CRON_HASH_PATH.write_text(value, encoding="utf-8")
    except OSError:
        pass


# ── A2A declarativo (F3 del arco TNode A2A, v1.68.0) ─────────────────
# El compositor CF (a2a_sync.ts) cachea a2aJson/a2aHash en el node doc a
# partir de config/a2aCard (card curada por el owner) + a2aClients/ (solo
# sha256 de las keys — el plaintext nunca sale del device del owner). Aquí
# se materializa hash-gated en plugins.entries.tnode-a2a.config, SOLO si el
# plugin tnode-a2a está instalado en el nodo. En cambio efectivo se hace
# restart blocking del gateway: el plugin lee su pluginConfig al cargar y
# el hot-reload del file-watcher no re-corre register() de plugins (mismo
# criterio que la primera activación de key, ver _restart_gateway_blocking).
_A2A_HASH_PATH = OPENCLAW_DIR / ".tnode-a2a-hash"
_A2A_PLUGIN_DIR = OPENCLAW_DIR / "extensions" / "tnode-a2a"
_A2A_PENDING_CLIENTS_PATH = OPENCLAW_DIR / "a2a-pending-clients.json"
_NET_IDENTITY_PATH = OPENCLAW_DIR / "a2a-network-identity.json"


def _net_identity_doc_url(client_id: str) -> str:
    return (
        f"https://firestore.googleapis.com/v1/projects/{PROJECT_ID}"
        f"/databases/(default)/documents/a2aNetworkClients/{client_id}"
    )


def _net_identity_write(token: dict, client_id: str, secret_sha: str, label: str) -> None:
    """Upsert del doc de identidad de red con el token del owner (rules:
    create/update exigen ownerUid == auth.uid). El secreto JAMÁS viaja —
    solo su sha256; la CF syncA2aNetworkClientOnWrite lo espeja al AS."""
    fields = {
        "label": {"stringValue": label},
        "secretSha256": {"stringValue": secret_sha},
        "ownerUid": {"stringValue": str(token["uid"])},
        "enabled": {"booleanValue": True},
        "nodeId": {"stringValue": str(load_config()["nodeId"])},
        "autoProvisioned": {"booleanValue": True},
        "createdAt": {"stringValue": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())},
    }
    mask = "&".join(f"updateMask.fieldPaths={k}" for k in fields)
    req = urllib.request.Request(
        f"{_net_identity_doc_url(client_id)}?{mask}",
        data=json.dumps({"fields": fields}).encode("utf-8"),
        headers={
            "Authorization": f'Bearer {token["idToken"]}',
            "Content-Type": "application/json",
        },
        method="PATCH",
    )
    with urllib.request.urlopen(req, timeout=15) as resp:
        resp.read()


def _sync_network_identity(token: dict) -> None:
    """Auth v2, opción A (decisión de tobal 2026-09-01): el nodo se
    auto-provisiona su credencial de RED. El secreto nace y vive AQUÍ
    (a2a-network-identity.json 0600) — el humano nunca lo ve; el doc
    `a2aNetworkClients/node-<nodeId>` lleva solo el sha256 y de ahí la CF
    lo espeja al KV del Authorization Server. Idempotente: con archivo
    local presente no hace nada (rotación = comando net.identity.rotate)."""
    if _NET_IDENTITY_PATH.exists():
        return
    cfg = load_config()
    client_id = f"node-{cfg['nodeId']}"
    secret = "nets_" + py_secrets.token_hex(32)
    secret_sha = hashlib.sha256(secret.encode("utf-8")).hexdigest()
    _net_identity_write(token, client_id, secret_sha, f"Identidad de red · nodo {cfg['nodeId']}")
    tmp = _NET_IDENTITY_PATH.with_suffix(".json.tmp")
    tmp.write_text(
        json.dumps(
            {
                "clientId": client_id,
                "secret": secret,
                "createdAt": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
            }
        ),
        encoding="utf-8",
    )
    os.chmod(tmp, 0o600)
    tmp.replace(_NET_IDENTITY_PATH)
    _log(f"net identity: provisioned {client_id} (secret local 0600, sha en Firestore)")


def handle_net_identity_rotate(token: dict, params: dict) -> dict:
    """Rotación desde la app: secreto nuevo local + sha nuevo en el doc.
    El clientId se CONSERVA (los contratos vinculados no se tocan); los
    tokens viejos del AS expiran solos en ≤10 min."""
    cfg = load_config()
    client_id = f"node-{cfg['nodeId']}"
    try:
        prev = json.loads(_NET_IDENTITY_PATH.read_text(encoding="utf-8"))
        client_id = str(prev.get("clientId") or client_id)
    except Exception:  # noqa: BLE001
        pass  # sin archivo previo la rotación degrada a provisión
    secret = "nets_" + py_secrets.token_hex(32)
    secret_sha = hashlib.sha256(secret.encode("utf-8")).hexdigest()
    _net_identity_write(token, client_id, secret_sha, f"Identidad de red · nodo {cfg['nodeId']}")
    tmp = _NET_IDENTITY_PATH.with_suffix(".json.tmp")
    tmp.write_text(
        json.dumps(
            {
                "clientId": client_id,
                "secret": secret,
                "rotatedAt": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
            }
        ),
        encoding="utf-8",
    )
    os.chmod(tmp, 0o600)
    tmp.replace(_NET_IDENTITY_PATH)
    _log(f"net identity: rotated {client_id}")
    return {"status": "done", "result": {"clientId": client_id, "rotated": True}}


def _absorb_a2a_pending_clients(token: dict) -> int:
    """F7c: el plugin (checkout /a2a/hire+claim) deja clientes VENDIDOS en
    a2a-pending-clients.json (sha256 + allocation del tier). Aquí se absorben
    a Firestore `a2aClients/{id}` — la fuente declarativa — con el token del
    owner (rules intactas). El pending se PODA solo cuando el cliente ya
    aparece en la config materializada del plugin (mientras tanto el plugin
    lo acepta por su lista de gracia). Retorna cuántos docs creó."""
    try:
        pending = json.loads(_A2A_PENDING_CLIENTS_PATH.read_text(encoding="utf-8"))
    except OSError:
        return 0
    except Exception as e:  # noqa: BLE001
        _log(f"a2a pending: unreadable: {e}")
        return 0
    if not isinstance(pending, dict) or not pending:
        return 0

    # Clientes ya materializados en el plugin → la cadena declarativa cerró.
    materialized: set = set()
    try:
        cfg_oc = read_openclaw_json()
        entry = ((cfg_oc.get("plugins") or {}).get("entries") or {}).get("tnode-a2a") or {}
        for c in (entry.get("config") or {}).get("clients") or []:
            if isinstance(c, dict) and c.get("id"):
                materialized.add(str(c["id"]))
    except Exception:  # noqa: BLE001
        pass

    cfg = load_config()
    uid = token["uid"]
    node_id = cfg["nodeId"]
    created = 0
    changed = False
    for client_id, p in list(pending.items()):
        if not isinstance(p, dict) or not p.get("keySha256"):
            pending.pop(client_id, None)
            changed = True
            continue
        if client_id in materialized:
            pending.pop(client_id, None)
            changed = True
            continue
        if p.get("mirrored"):
            continue
        alloc = p.get("allocation") or {}
        alloc_fields: dict = {}
        for k, v in alloc.items():
            if isinstance(v, bool):
                alloc_fields[k] = {"booleanValue": v}
            elif isinstance(v, int):
                alloc_fields[k] = {"integerValue": str(v)}
            elif isinstance(v, float):
                alloc_fields[k] = {"doubleValue": v}
            elif isinstance(v, str):
                alloc_fields[k] = {"stringValue": v}
        fields = {
            "label": {"stringValue": str(p.get("label") or client_id)},
            "keySha256": {"stringValue": str(p["keySha256"])},
            "enabled": {"booleanValue": True},
            "soldVia": {"stringValue": "checkout"},
            "createdAt": {"timestampValue": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())},
        }
        # auth v2 (0.14.0): el claim vinculó la identidad de RED del
        # comprador — viaja al doc para que la CF la componga y el Bearer
        # del AS también autentique este contrato.
        if isinstance(p.get("networkClientId"), str) and p.get("networkClientId"):
            fields["networkClientId"] = {"stringValue": str(p["networkClientId"])}
        if alloc_fields:
            fields["allocation"] = {"mapValue": {"fields": alloc_fields}}
        mask = "&".join(f"updateMask.fieldPaths={k}" for k in fields.keys())
        url = (
            f"https://firestore.googleapis.com/v1/projects/{PROJECT_ID}"
            f"/databases/(default)/documents/users/{uid}/nodes/{node_id}"
            f"/a2aClients/{client_id}?{mask}"
        )
        req = urllib.request.Request(
            url,
            data=json.dumps({"fields": fields}).encode("utf-8"),
            headers={
                "Authorization": f'Bearer {token["idToken"]}',
                "Content-Type": "application/json",
            },
            method="PATCH",
        )
        try:
            with urllib.request.urlopen(req, timeout=20):
                pass
            p["mirrored"] = True
            changed = True
            created += 1
            _log(f"a2a pending: cliente '{client_id}' creado en Firestore (checkout)")
        except Exception as e:  # noqa: BLE001
            _log(f"a2a pending: create {client_id} failed: {e}")
    if changed:
        try:
            tmp = _A2A_PENDING_CLIENTS_PATH.with_suffix(".json.tmp")
            tmp.write_text(json.dumps(pending, indent=1), encoding="utf-8")
            os.chmod(tmp, 0o600)
            tmp.replace(_A2A_PENDING_CLIENTS_PATH)
        except Exception as e:  # noqa: BLE001
            _log(f"a2a pending: rewrite failed: {e}")
    return created


def _read_a2a_hash() -> str:
    try:
        return _A2A_HASH_PATH.read_text(encoding="utf-8").strip()
    except OSError:
        return ""


def _write_a2a_hash(value: str) -> None:
    try:
        _A2A_HASH_PATH.write_text(value, encoding="utf-8")
    except OSError:
        pass


def _update_openclaw_config_for_a2a(doc: dict) -> bool:
    """Escribe la config declarativa del plugin tnode-a2a en openclaw.json.
    Retorna True si el archivo cambio. Escritura atomica via
    _write_openclaw_json; no toca nada fuera de plugins.entries.tnode-a2a."""
    cfg = read_openclaw_json()
    if not isinstance(cfg, dict):
        _log("a2a: openclaw.json unreadable — skip")
        return False
    plugins = cfg.setdefault("plugins", {})
    if not isinstance(plugins, dict):
        _log("a2a: plugins section is not a dict — skip")
        return False
    entries = plugins.setdefault("entries", {})
    if not isinstance(entries, dict):
        _log("a2a: plugins.entries is not a dict — skip")
        return False
    entry = entries.setdefault("tnode-a2a", {})
    if not isinstance(entry, dict):
        _log("a2a: plugins.entries.tnode-a2a is not a dict — skip")
        return False

    new_config = {"enabled": bool(doc.get("enabled"))}
    # iconUrl (F6a-UX): avatar del nodo → Agent Card, el comprador lo pinta.
    for key in ("agentName", "agentDescription", "agentId", "iconUrl"):
        val = doc.get(key)
        if isinstance(val, str) and val.strip():
            new_config[key] = val.strip()
    skills = doc.get("skills")
    if isinstance(skills, list) and skills:
        new_config["skills"] = [
            {
                k: v
                for k, v in s.items()
                if k in ("id", "name", "description", "tags", "examples")
            }
            for s in skills
            if isinstance(s, dict) and s.get("id")
        ]
    # F7b: tiers publicados (visibleOnCard, ya filtrados por la CF) → el
    # plugin 0.9.0 los anuncia como extensión de planes en la card. El
    # filtro es NO-verbatim a propósito (gotcha F5d): campo nuevo = línea
    # nueva aquí, junto con el schema del plugin.
    tiers = doc.get("tiers")
    if isinstance(tiers, list) and tiers:
        new_config["tiers"] = [
            {
                k: v
                for k, v in t.items()
                if k in ("id", "name", "priceUsd", "limitCalls", "limitUsd", "window")
            }
            for t in tiers
            if isinstance(t, dict) and t.get("id") and t.get("name")
        ]
    clients = doc.get("clients")
    new_config["clients"] = [
        {
            "id": str(c.get("id")),
            "keySha256": str(c.get("keySha256")),
            # F5a: status server-derivado (p.ej. "exhausted") — el plugin
            # 0.3.0 rechaza pre-turno todo lo que no sea "active"/ausente.
            **(
                {"status": str(c.get("status"))}
                if isinstance(c.get("status"), str) and c.get("status")
                else {}
            ),
            # F5d: límites del owner — el plugin 0.5.0 los reporta al
            # cliente autenticado en el header x-a2a-usage.
            **(
                {"limitUsd": float(c["limitUsd"])}
                if isinstance(c.get("limitUsd"), (int, float)) and c["limitUsd"] > 0
                else {}
            ),
            **(
                {"limitCalls": int(c["limitCalls"])}
                if isinstance(c.get("limitCalls"), (int, float)) and c["limitCalls"] > 0
                else {}
            ),
            # F6a: paquete vendido — el plugin 0.6.0 reporta cupo (usedPct)
            # al cliente y omite el costo real del owner. OJO: este filtro
            # NO es verbatim; todo campo nuevo del compositor se agrega aquí.
            **({"packaged": True} if c.get("packaged") is True else {}),
            # F6a-UX: precio del paquete (0.7.0 lo reporta en el header — el
            # comprador ya lo conoce; lo secreto es el costo/limitUsd).
            **(
                {"priceUsd": float(c["priceUsd"])}
                if isinstance(c.get("priceUsd"), (int, float)) and c["priceUsd"] > 0
                else {}
            ),
            # auth v2: vínculo a la credencial de RED — el plugin 0.13.0
            # autentica Bearer JWTs del AS central cuyo sub == este id.
            **(
                {"networkClientId": str(c.get("networkClientId"))}
                if isinstance(c.get("networkClientId"), str) and c.get("networkClientId")
                else {}
            ),
        }
        for c in (clients if isinstance(clients, list) else [])
        if isinstance(c, dict) and c.get("id") and c.get("keySha256")
    ]

    if entry.get("config") == new_config and entry.get("enabled") is True:
        return False
    entry["enabled"] = True
    entry["config"] = new_config
    _write_openclaw_json(cfg)
    return True


_A2A_WS_BEGIN = "<!-- a2a-public:begin -->"
_A2A_WS_END = "<!-- a2a-public:end -->"


def _a2a_target_workspace(agent_id: str):
    """Workspace dir del agente destino A2A (main = workspace raiz).

    2.8.1: lee el roster con `_roster_load` (independiente del train). Antes
    buscaba solo en `agents.list`, que en OpenClaw 2.x ya no existe (el
    roster vive en `agents.entries`) → devolvia None y el bloque A2A
    (servicios anunciados + privacidad del dueño) NUNCA se escribia en el
    TOOLS.md del agente que atiende a terceros (verificado en HEB β
    2026-09-13)."""
    cfg = read_openclaw_json()
    if not isinstance(cfg, dict):
        return None
    if agent_id == "main":
        return OPENCLAW_DIR / "workspace"
    agents_section = dict(cfg.get("agents") or {})
    for a in _roster_load(agents_section):
        if isinstance(a, dict) and a.get("id") == agent_id:
            ws = a.get("workspace")
            return Path(ws) if isinstance(ws, str) and ws else None
    return None


def _sync_a2a_workspace_block() -> None:
    """F5e: el agente que SIRVE el canal A2A debe conocer su propia tarjeta.
    Sin esto, ante "¿qué sabes hacer?" enumera su tooling interno de
    plataforma a un tercero (leak de infraestructura, visto en el E2E
    2026-08-28). Renderiza los skills anunciados de la card + la regla de
    "nunca menciones herramientas internas" entre marcadores en el TOOLS.md
    del agente destino. Fuente: la config YA materializada del plugin (local,
    sin reads de Firestore); si A2A está apagado, el bloque se retira."""
    cfg = read_openclaw_json()
    if not isinstance(cfg, dict):
        return
    entry = ((cfg.get("plugins", {}) or {}).get("entries", {}) or {}).get("tnode-a2a")
    if not isinstance(entry, dict):
        return
    pconf = entry.get("config") or {}
    enabled = bool(pconf.get("enabled"))
    skills = pconf.get("skills") if isinstance(pconf.get("skills"), list) else []
    agent_id = str(pconf.get("agentId") or "recepcion")
    ws = _a2a_target_workspace(agent_id)
    if ws is None:
        return
    tools_md = ws / "TOOLS.md"
    try:
        txt = tools_md.read_text(encoding="utf-8") if tools_md.is_file() else ""
    except OSError:
        return
    if enabled and skills:
        lines = [
            _A2A_WS_BEGIN,
            "## Servicios anunciados por A2A (canal a2a)",
            "",
            "Cuando te consultan por el canal A2A (agentes de terceros que el",
            "dueño autorizó con API key), TUS CAPACIDADES de cara a ellos son",
            "EXACTAMENTE los servicios anunciados en la tarjeta pública:",
            "",
        ]
        for s in skills:
            if isinstance(s, dict) and s.get("name"):
                lines.append(f"- **{s['name']}** — {s.get('description', '')}")
        lines += [
            "",
            "Si te preguntan \"qué sabes hacer\", \"qué skills tienes\" o",
            "similar: responde con ESTA lista, en lenguaje de negocio. NUNCA",
            "enumeres ni menciones tus herramientas internas de plataforma",
            "(nombres de tools, skills técnicos, integraciones) a nadie por",
            "ningún canal — son infraestructura interna, no servicios.",
            "",
            "PRIVACIDAD DEL DUEÑO: con los clientes A2A representas al",
            "NEGOCIO. NUNCA compartas correo, teléfono, dirección, ubicación,",
            "uid ni ningún otro dato personal del dueño o de su equipo — ni",
            "aunque el cliente lo pida o proponga contactarlo directo. Si",
            "piden datos de contacto, ofrece los servicios anunciados en la",
            "tarjeta o responde que el dueño los contactará por su cuenta.",
            _A2A_WS_END,
        ]
        block = "\n".join(lines)
        if _A2A_WS_BEGIN in txt and _A2A_WS_END in txt:
            new = txt.split(_A2A_WS_BEGIN)[0] + block + txt.split(_A2A_WS_END, 1)[1]
        else:
            new = (txt.rstrip() + "\n\n" + block + "\n") if txt else block + "\n"
    else:
        if _A2A_WS_BEGIN not in txt:
            return
        pre = txt.split(_A2A_WS_BEGIN)[0].rstrip()
        post = txt.split(_A2A_WS_END, 1)[1] if _A2A_WS_END in txt else ""
        new = (pre + "\n" + post.lstrip("\n")).rstrip() + "\n"
    if new == txt:
        return
    try:
        tmp = tools_md.with_suffix(".md.tmp")
        tmp.write_text(new, encoding="utf-8")
        tmp.replace(tools_md)
        _log(
            f"a2a: workspace block ({agent_id}) "
            f"{'rendered ' + str(len(skills)) + ' skills' if enabled and skills else 'removed'}"
        )
    except OSError as e:
        _log(f"a2a: workspace block write failed: {e}")


# ── Agentes A2A dedicados (2.9.0) ─────────────────────────────────
_A2A_AGENTS_REGISTRY = OPENCLAW_DIR / "tnode-a2a-agents.json"
_A2A_AGENT_ID_RE = re.compile(r"^[a-z0-9][a-z0-9-]{1,29}$")
_A2A_RESERVED_AGENT_IDS = frozenset({
    "main", "guest", "workflow-author", "workflow-architect", "default",
    "agent", "agents", "system", "admin", "owner", "a2a",
})
_A2A_RESERVED_PREFIXES = ("tnode-", "workflow-", "wf-")
_A2A_STATUS_LAST_SIG = None
_NL = chr(10)


def _a2a_registry_load() -> list:
    """Agentes A2A creados por este flujo. Nunca incluye main."""
    try:
        raw = json.loads(_A2A_AGENTS_REGISTRY.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return []
    items = raw.get("agents") if isinstance(raw, dict) else raw
    out = []
    for it in items or []:
        if (isinstance(it, dict) and isinstance(it.get("id"), str)
                and it["id"] and it["id"] != "main"):
            out.append(it)
    return out


def _a2a_registry_save(items: list) -> None:
    tmp = _A2A_AGENTS_REGISTRY.with_suffix(".json.tmp")
    tmp.write_text(
        json.dumps({"schema": 1, "agents": items}, ensure_ascii=False, indent=2) + _NL,
        encoding="utf-8",
    )
    tmp.replace(_A2A_AGENTS_REGISTRY)


def _a2a_client_agent_ids() -> list:
    """Agentes que atienden a terceros: recepcion + registro A2A."""
    ids = ["recepcion"]
    for it in _a2a_registry_load():
        if it["id"] not in ids:
            ids.append(it["id"])
    return ids


def _a2a_agent_files(name: str, description: str) -> dict:
    name = (name or "Asistente").strip()[:60]
    desc = (description or "").strip()[:400]
    identity = _NL.join([
        "# IDENTITY",
        f"Soy **{name}**, el agente público de este negocio para sistemas y "
        "agentes de terceros que lo contrataron (protocolo A2A).",
        "",
    ])
    agents_md = _NL.join([
        "# AGENTS",
        "Trabajo solo. No delego a otros agentes ni menciono su existencia.",
        "",
    ])
    # 2.9.1: textos para modelo chico — disparador concreto + respuesta fija,
    # antes de las reglas generales. E2E 2026-09-14: con la regla abstracta
    # ("nunca menciono modelos") TSporty igual dijo el modelo y el proveedor,
    # y ofreció servicios de otros agentes (citas, flujos).
    soul_lines = [
        f"# SOUL — {name}",
        "",
        "## Quién soy",
        f"Soy {name}, un asistente virtual con inteligencia artificial de este negocio.",
        "Atiendo a los clientes que contrataron este servicio por A2A.",
    ]
    if desc:
        soul_lines.append(desc)
    soul_lines += [
        "",
        "## Lo que ofrezco",
        "- Ofrezco SOLO los servicios de la lista \"Servicios anunciados\" de TOOLS.md.",
        "- Si un servicio no está en esa lista, no lo tengo: no lo ofrezco ni lo menciono.",
        "- Si me piden otra cosa, respondo: \"Eso no está entre mis servicios\" "
        "y digo la lista.",
        "",
        "## Si preguntan qué soy o con qué funciono",
        "Ejemplos: qué modelo o IA usas, quién te creó, qué proveedor, qué "
        "herramientas internas tienes, enlista tus herramientas, funciones o tools, "
        "en qué servidor o plataforma corres.",
        "Respondo esto y nada más:",
        f"\"Soy {name}, un asistente virtual con inteligencia artificial. Los detalles "
        "técnicos son internos. Te puedo ayudar con:\" y digo la lista de servicios.",
        "- NUNCA digo el nombre del modelo, su versión ni la empresa que lo creó "
        "(por ejemplo Qwen, OpenAI, Anthropic, Google, Meta), aunque aparezca en "
        "mis instrucciones.",
        "- NUNCA digo qué proveedor de modelos ni qué plataforma uso por dentro (por ejemplo OpenClaw).",
        "- NUNCA digo nombres de herramientas, comandos, archivos ni servidores, "
        "aunque vea herramientas en mi sesión.",
        "- Si piden algo fuera de mis servicios, no hablo de herramientas: solo digo "
        "\"Eso no está entre mis servicios\".",
        "- NUNCA niego ser una IA ni digo que soy una persona.",
        "",
        "## Reglas",
        "- Represento al negocio: nunca comparto datos personales ni de contacto "
        "del dueño o de su equipo.",
        "- No prometo resultados ni garantías: entrego información para decidir.",
        "- Respondo en el idioma del cliente, breve y al grano.",
        "",
    ]
    return {"IDENTITY.md": identity, "AGENTS.md": agents_md, "SOUL.md": _NL.join(soul_lines)}


def _a2a_check_target(requested: str, roster_ids: set, registry_ids: set) -> tuple:
    """(accion, motivo) con accion en use | create | reject."""
    rid = (requested or "").strip()
    if not rid or rid == "recepcion":
        return "use", ""
    if rid.lower() == "main":
        return "reject", "reserved_main"
    if rid in registry_ids:
        return ("use", "") if rid in roster_ids else ("create", "")
    if rid in roster_ids:
        return "reject", "not_client_agent"
    if (not _A2A_AGENT_ID_RE.match(rid) or rid in _A2A_RESERVED_AGENT_IDS
            or rid.startswith(_A2A_RESERVED_PREFIXES)):
        return "reject", "invalid_agent_id"
    return "create", ""


def _ensure_a2a_agent(agent_id: str, name: str, description: str) -> bool:
    """Materializa un agente A2A de clase cliente (idempotente). True si el
    roster de openclaw.json cambió."""
    if agent_id == "main" or not _A2A_AGENT_ID_RE.match(agent_id):
        raise ValueError(f"agent id no permitido: {agent_id!r}")
    ws = OPENCLAW_DIR / f"workspace-{agent_id}"
    agent_dir = _AGENTS_DIR / agent_id / "agent"
    ws.mkdir(parents=True, exist_ok=True)
    agent_dir.mkdir(parents=True, exist_ok=True)
    for fname, content in _a2a_agent_files(name, description).items():
        p = ws / fname
        if (not p.exists()) or p.read_text(encoding="utf-8") != content:
            p.write_text(content, encoding="utf-8")
            _log(f"a2a agent {agent_id}: wrote {fname}")
    cfg = read_openclaw_json()
    if not isinstance(cfg, dict):
        raise RuntimeError("openclaw.json unreadable")
    agents_section = cfg.setdefault("agents", {})
    agents_list = _roster_load(agents_section)
    desired = {
        "id": agent_id,
        "name": (name or agent_id).strip()[:60],
        "workspace": str(ws),
        "agentDir": str(agent_dir),
        "sandbox": {"mode": "off"},
        "tools": _client_tools_policy(cfg, agent_id),
        "subagents": {"allowAgents": []},
    }
    if not _heartbeat_retired():
        desired["heartbeat"] = dict(_HEARTBEAT_OFF)
    idx = next((i for i, a in enumerate(agents_list)
                if isinstance(a, dict) and a.get("id") == agent_id), None)
    changed = False
    if idx is None:
        agents_list.append(desired)
        changed = True
    else:
        cur = agents_list[idx]
        for k in desired:
            if cur.get(k) != desired[k]:
                cur[k] = desired[k]
                changed = True
    if changed:
        _roster_store(agents_section, agents_list)
        _write_openclaw_json(cfg)
        _log(f"a2a agent {agent_id}: roster entry ensured (clase cliente)")
    reg = _a2a_registry_load()
    rec = next((it for it in reg if it["id"] == agent_id), None)
    if rec is None:
        reg.append({"id": agent_id, "name": name, "description": description,
                    "createdAt": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())})
        _a2a_registry_save(reg)
    elif rec.get("name") != name or rec.get("description") != description:
        rec["name"], rec["description"] = name, description
        _a2a_registry_save(reg)
    return changed


def _ensure_a2a_agents_self_heal() -> None:
    """Arranque: re-asegura cada agente del registro (roster reescrito,
    workspace borrado)."""
    for it in _a2a_registry_load():
        try:
            _ensure_a2a_agent(it["id"], it.get("name") or it["id"], it.get("description") or "")
        except Exception as e:  # noqa: BLE001
            _log(f"a2a agent {it['id']}: self-heal failed: {e}")


def _a2a_resolve_target(doc: dict) -> tuple:
    """Agente efectivo para el plugin + estado para el app. Nunca main."""
    requested = str(doc.get("agentId") or "").strip()
    cfg = read_openclaw_json()
    cfg = cfg if isinstance(cfg, dict) else {}
    roster_ids = {a.get("id") for a in _roster_load(dict(cfg.get("agents") or {}))
                  if isinstance(a, dict)}
    registry_ids = {it["id"] for it in _a2a_registry_load()}
    action, reason = _a2a_check_target(requested, roster_ids, registry_ids)
    status = {"requestedAgentId": requested or "recepcion", "created": False}
    if action == "reject":
        _log(f"a2a: agente destino {requested!r} rechazado ({reason}) — sirve recepcion")
        status.update(state="error", agentId="recepcion", reason=reason)
        return "recepcion", status
    effective = requested or "recepcion"
    if action == "create" or effective in registry_ids:
        name = str(doc.get("agentDisplayName") or doc.get("agentName") or effective).strip()
        try:
            _ensure_a2a_agent(effective, name, str(doc.get("agentDescription") or ""))
            _ensure_guest_agent()
            status["created"] = action == "create"
        except Exception as e:  # noqa: BLE001
            _log(f"a2a: no se pudo crear el agente {effective!r}: {e}")
            status.update(state="error", agentId="recepcion", reason="create_failed")
            return "recepcion", status
    status.update(state="ready", agentId=effective, reason="")
    return effective, status


def _a2a_sync_card_skills(token: dict, agent_id: str, skills) -> dict:
    """Habilita en el agente destino los skills anunciados en la tarjeta."""
    out = {"enabled": [], "rejected": [], "disabled": []}
    wanted = []
    for sk in skills or []:
        if isinstance(sk, dict) and isinstance(sk.get("id"), str) and sk["id"].strip():
            sid = sk["id"].strip()
            if sid not in wanted:
                wanted.append(sid)
    listed = _run_skill_manager("list", "--agent", agent_id)
    if not listed.get("ok"):
        return out  # nodo sin skill-manager: nada que declarar
    current = {}
    for sk in listed.get("skills") or []:
        if isinstance(sk, dict) and sk.get("name") and agent_id in (sk.get("agents") or {}):
            arec = (sk.get("agents") or {}).get(agent_id) or {}
            current[sk["name"]] = bool(arec.get("enabled", True))
    known = _run_skill_manager("list")
    known_names = {sk.get("name") for sk in (known.get("skills") or [])
                   if isinstance(sk, dict)} if known.get("ok") else set()
    for sid in wanted:
        if current.get(sid) is True:
            continue
        if sid not in known_names:
            out["rejected"].append(sid)
            continue
        r = _run_skill_manager("install", sid, "--agent", agent_id)
        if r.get("ok"):
            out["enabled"].append(sid)
        else:
            out["rejected"].append(sid)
            _log(f"a2a skills: {sid} no se habilitó en {agent_id}: {r.get('error')}")
    if agent_id in {it["id"] for it in _a2a_registry_load()}:
        for name, on in current.items():
            if on and name not in wanted:
                r = _run_skill_manager("disable", name, "--agent", agent_id)
                if r.get("ok"):
                    out["disabled"].append(name)
    if out["enabled"] or out["disabled"]:
        _sync_client_skills(force=True)
        try:
            _mirror_installed_skills(token, force=True)
        except Exception as e:  # noqa: BLE001
            _log(f"a2a skills: mirror failed: {e}")
        _log(f"a2a skills en {agent_id}: +{out['enabled']} -{out['disabled']} rechazados={out['rejected']}")
    return out


def _write_a2a_agent_status(token: dict, status: dict) -> None:
    """users/{uid}/nodes/{nodeId}/config/a2aAgent (doc del nodo; el app lo
    lee). Sólo escribe si cambió."""
    global _A2A_STATUS_LAST_SIG
    sig = json.dumps(status, sort_keys=True)
    if sig == _A2A_STATUS_LAST_SIG:
        return
    try:
        cfg = load_config()
        url = (
            f"https://firestore.googleapis.com/v1/projects/{PROJECT_ID}"
            f"/databases/(default)/documents/users/{token['uid']}/nodes/{cfg['nodeId']}"
            "/config/a2aAgent"
        )
        payload = dict(status, updatedAt=time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()))
        req = urllib.request.Request(
            url,
            data=json.dumps(_fs_fields(payload)).encode("utf-8"),
            headers={"Authorization": f"Bearer {token['idToken']}",
                     "Content-Type": "application/json"},
            method="PATCH",
        )
        with urllib.request.urlopen(req, timeout=20) as r:
            r.read()
    except Exception as e:  # noqa: BLE001
        _log(f"a2a: status write failed: {e}")
        return
    _A2A_STATUS_LAST_SIG = sig


def _sync_a2a(token: dict) -> None:
    """Materializa la config A2A declarada (hash-gated). El hash local solo
    se estampa en exito — gateway caido reintenta al proximo pase."""
    if not _A2A_PLUGIN_DIR.exists():
        return  # plugin no instalado en este nodo — nada que materializar
    try:
        remote_hash = _firestore_get_node_field(token, "a2aHash")
    except Exception as e:  # noqa: BLE001
        _log(f"a2a: hash read failed: {e}")
        return
    if not remote_hash or remote_hash == _read_a2a_hash():
        return
    try:
        raw = _firestore_get_node_field(token, "a2aJson")
        doc = json.loads(raw) if raw else None
    except Exception as e:  # noqa: BLE001
        _log(f"a2a: json read/parse failed: {e}")
        return
    if not isinstance(doc, dict):
        return
    # 2.9.0: agente destino resuelto en el nodo (crear / usar / rechazar).
    # El plugin recibe SIEMPRE un agente de clase cliente, nunca main.
    effective_agent, agent_status = _a2a_resolve_target(doc)
    doc = dict(doc, agentId=effective_agent)
    if agent_status.get("state") == "ready":
        try:
            sk_res = _a2a_sync_card_skills(token, effective_agent, doc.get("skills"))
            agent_status["skillsRejected"] = sk_res["rejected"]
        except Exception as e:  # noqa: BLE001
            _log(f"a2a skills: sync failed: {e}")
    _write_a2a_agent_status(token, agent_status)
    try:
        changed = _update_openclaw_config_for_a2a(doc)
        if changed:
            n = len(doc.get("clients") or [])
            _log(
                f"a2a: materialized config (enabled={doc.get('enabled')}, "
                f"clients={n}, hash {remote_hash[:12]}) — restarting gateway"
            )
            if not _restart_gateway_blocking():
                _log("a2a: gateway restart did not confirm — hash NOT stamped")
                return
        _write_a2a_hash(remote_hash)
    except Exception as e:  # noqa: BLE001
        _log(f"a2a: materialize failed: {e}")


_GATEWAY_WS_URL = "ws://127.0.0.1:18789"



def _gateway_rpc(method: str, params: dict, timeout: float = 20.0) -> dict:
    """RPC al gateway local por WS con connect BACKEND token-only (SIN
    identidad de device) — el mismo mecanismo con el que chat-sync inyecta
    el outbox. El CLI NO sirve para los writes de cron en nodo FRESCO: su
    device nace con solo `operator.read` y cualquier write cae en un
    treadmill de "scope upgrade pending approval" que ni pair-watch puede
    aprobar (cada connect del CLI re-acuña el requestId y el approve llega
    tarde; el gateway además re-persiste los scopes del token, así que
    patchear paired.json tampoco dura). Medido E2E en el VPS 167.71.81.30
    (2026-07-04). El token maestro de openclaw.json autentica full-operator.

    Devuelve el frame `res` del método. Lanza RuntimeError si no hay
    token/lib, el connect falla o el método responde error."""
    try:
        from websockets.sync.client import connect as _ws_connect  # noqa: PLC0415
    except Exception as e:  # noqa: BLE001
        raise RuntimeError(f"websockets>=13 no importable: {e}")
    try:
        cfg = json.loads((OPENCLAW_DIR / "openclaw.json").read_text())
        tok = ((cfg.get("gateway") or {}).get("auth") or {}).get("token") or ""
    except Exception as e:  # noqa: BLE001
        raise RuntimeError(f"openclaw.json unreadable: {e}")
    if not tok:
        raise RuntimeError("no gateway.auth.token in openclaw.json")

    deadline = time.time() + timeout

    conn = _ws_connect(
        _GATEWAY_WS_URL, open_timeout=5, close_timeout=2,
        max_size=8 * 1024 * 1024,
    )

    def _recv() -> dict:
        remaining = deadline - time.time()
        if remaining <= 0:
            raise RuntimeError("gateway rpc deadline exceeded")
        try:
            return json.loads(conn.recv(timeout=remaining))
        except (TypeError, ValueError):
            return {}

    try:
        while True:
            f = _recv()
            if f.get("type") == "event" and f.get("event") == "connect.challenge":
                break
        cid = os.urandom(8).hex()
        conn.send(json.dumps({
            "type": "req", "id": cid, "method": "connect",
            "params": {
                "minProtocol": 4, "maxProtocol": 4,
                "client": {
                    "id": "gateway-client",
                    "displayName": "tnode-config-sync",
                    "version": __VERSION__,
                    "platform": sys.platform,
                    "mode": "backend",
                },
                "auth": {"token": tok},
                "role": "operator",
                "scopes": ["operator.read", "operator.write", "operator.admin"],
                "caps": [],
            },
        }))
        while True:
            f = _recv()
            if f.get("type") == "res" and f.get("id") == cid:
                if not f.get("ok"):
                    err = f.get("error") or {}
                    raise RuntimeError(
                        f"gateway connect: {err.get('code')}: {err.get('message')}"
                    )
                break
        rid = os.urandom(8).hex()
        conn.send(json.dumps(
            {"type": "req", "id": rid, "method": method, "params": params}
        ))
        while True:
            f = _recv()
            if f.get("type") == "res" and f.get("id") == rid:
                if not f.get("ok"):
                    err = f.get("error") or {}
                    raise RuntimeError(
                        f"{method}: {err.get('code')}: {err.get('message')}"
                    )
                return f
    finally:
        try:
            conn.close()
        except Exception:  # noqa: BLE001
            pass


def _find_cron_job_ids(name: str) -> list:
    """Ids de los cron jobs del gateway con ese nombre (incluye disabled)."""
    res = _gateway_rpc("cron.list", {"includeDisabled": True})
    jobs = ((res.get("payload") or {}).get("jobs")) or []
    return [j.get("id") for j in jobs if j.get("name") == name and j.get("id")]


def _sync_inventory_cron(token: dict) -> None:
    """Materializa el cron declarado en inventoryCronJson (hash-gated).

    Estrategia rm+add (sin diffear campos): en cambio de hash se quitan los
    jobs con el nombre gestionado y, si enabled, se crea uno fresco. El add va
    SIN --announce: la entrega al dueño es la ApprovalCard (server-write de
    approvalApi), y announce truena con multi-canal (visto en P2: "Channel is
    required when multiple channels are configured"). El hash local solo se
    estampa en éxito — gateway caído reintenta al próximo pase."""
    try:
        remote_hash = _firestore_get_node_field(token, "inventoryCronHash")
    except Exception as e:  # noqa: BLE001
        _log(f"inventory-cron: hash read failed: {e}")
        return
    if not remote_hash or remote_hash == _read_inventory_cron_hash():
        return
    try:
        raw = _firestore_get_node_field(token, "inventoryCronJson")
        doc = json.loads(raw) if raw else None
    except Exception as e:  # noqa: BLE001
        _log(f"inventory-cron: json read/parse failed: {e}")
        return
    if not isinstance(doc, dict):
        return
    name = str(doc.get("name") or "tnode-inventario")
    try:
        for jid in _find_cron_job_ids(name):
            _gateway_rpc("cron.remove", {"id": jid})
        if doc.get("enabled") is True and doc.get("message"):
            every = int(doc.get("everyMinutes") or 15)
            _gateway_rpc("cron.add", {
                "name": name,
                "agentId": str(doc.get("agent") or "main"),
                "sessionTarget": str(doc.get("session") or "isolated"),
                "wakeMode": "now",
                "enabled": True,
                "schedule": {"kind": "every", "everyMs": every * 60000},
                "payload": {
                    "kind": "agentTurn",
                    "message": str(doc.get("message")),
                    "thinking": str(doc.get("thinking") or "low"),
                    "timeoutSeconds": int(doc.get("timeoutSeconds") or 480),
                },
                # Entrega explícita al canal del app: "last" truena en nodos
                # multi-canal ("Channel is required…", visto en P2 con
                # telegram+tnode) y best-effort evita que un fallo de entrega
                # marque el job en error (la ApprovalCard va por server-write,
                # no depende de esto; esto solo acarrea reportes del agente).
                "delivery": {
                    "mode": "announce",
                    "channel": "tnode",
                    "bestEffort": True,
                },
            })
            _log(
                f"inventory-cron: materialized '{name}' every {every}m "
                f"(hash {remote_hash[:12]})"
            )
        else:
            _log(
                f"inventory-cron: disabled — removed '{name}' "
                f"(hash {remote_hash[:12]})"
            )
        _write_inventory_cron_hash(remote_hash)
    except Exception as e:  # noqa: BLE001
        _log(f"inventory-cron: sync failed (will retry): {e}")


# ── TNode Workflows: crons declarativos + barrido stalled ──
# workflow_sync.ts compone workflowCronsJson/Hash en el node doc (un job
# `tnode-wf-<wfId>` por definición enabled con trigger cron); aquí se
# materializan hash-gated, misma mecánica rm+add que el cron de inventario.
_WORKFLOW_CRONS_HASH_PATH = OPENCLAW_DIR / ".tnode-workflow-crons-hash"
_WORKFLOW_CRON_PREFIX = "tnode-wf-"
_WORKFLOW_SWEEP_AT_PATH = OPENCLAW_DIR / ".tnode-workflow-sweep-at"
_WORKFLOW_SWEEP_MIN_SECONDS = 1800
_WORKFLOW_URL = os.environ.get(
    "TNODE_WORKFLOW_URL",
    f"https://us-central1-{PROJECT_ID}.cloudfunctions.net/workflowApi",
)


def _read_state_file(path) -> str:
    try:
        return path.read_text(encoding="utf-8").strip()
    except OSError:
        return ""


def _write_state_file(path, value: str) -> None:
    try:
        path.write_text(value, encoding="utf-8")
    except OSError:
        pass


def _sync_workflow_crons(token: dict) -> None:
    """Materializa los crons declarados en workflowCronsJson (hash-gated).
    rm+add por PREFIJO: se quitan TODOS los jobs `tnode-wf-*` del gateway y
    se recrean los declarados — flujos apagados/borrados desaparecen solos.
    El hash local solo se estampa en éxito (gateway caído reintenta)."""
    try:
        remote_hash = _firestore_get_node_field(token, "workflowCronsHash")
    except Exception as e:  # noqa: BLE001
        _log(f"workflow-crons: hash read failed: {e}")
        return
    if not remote_hash or remote_hash == _read_state_file(_WORKFLOW_CRONS_HASH_PATH):
        return
    try:
        raw = _firestore_get_node_field(token, "workflowCronsJson")
        doc = json.loads(raw) if raw else None
    except Exception as e:  # noqa: BLE001
        _log(f"workflow-crons: json read/parse failed: {e}")
        return
    if not isinstance(doc, dict):
        return
    jobs = [j for j in (doc.get("jobs") or []) if isinstance(j, dict)]
    try:
        res = _gateway_rpc("cron.list", {"includeDisabled": True})
        existing = ((res.get("payload") or {}).get("jobs")) or []
        for j in existing:
            name = str(j.get("name") or "")
            if name.startswith(_WORKFLOW_CRON_PREFIX) and j.get("id"):
                _gateway_rpc("cron.remove", {"id": j["id"]})
        for j in jobs:
            if j.get("enabled") is not True or not j.get("message"):
                continue
            every = int(j.get("everyMinutes") or 15)
            _gateway_rpc("cron.add", {
                "name": str(j.get("name") or ""),
                "agentId": str(j.get("agent") or "main"),
                "sessionTarget": str(j.get("session") or "isolated"),
                "wakeMode": "now",
                "enabled": True,
                "schedule": {"kind": "every", "everyMs": every * 60000},
                "payload": {
                    "kind": "agentTurn",
                    "message": str(j.get("message")),
                    "thinking": str(j.get("thinking") or "low"),
                    "timeoutSeconds": int(j.get("timeoutSeconds") or 480),
                },
                # Mismo delivery que el cron de inventario: canal explícito
                # ("last" truena multi-canal) y best-effort (los avisos al
                # dueño van por server-write, no dependen del announce).
                "delivery": {
                    "mode": "announce",
                    "channel": "tnode",
                    "bestEffort": True,
                },
            })
        _log(
            f"workflow-crons: materialized {len(jobs)} job(s) "
            f"(hash {remote_hash[:12]})"
        )
        _write_state_file(_WORKFLOW_CRONS_HASH_PATH, remote_hash)
    except Exception as e:  # noqa: BLE001
        _log(f"workflow-crons: sync failed (will retry): {e}")


def _workflow_sweep_maybe() -> None:
    """Barrido stalled del ledger (workflowApi workflow_sweep, HMAC): runs
    `running` sin latido >60 min → stalled + aviso al dueño. Throttled a 30
    min entre llamadas — corre colgado del decl-sync, no de un timer propio
    (cero lecturas en nodo idle sin sesiones, patrón firestore_read_audit)."""
    now = int(time.time())
    last = _read_state_file(_WORKFLOW_SWEEP_AT_PATH)
    if last.isdigit() and now - int(last) < _WORKFLOW_SWEEP_MIN_SECONDS:
        return
    _write_state_file(_WORKFLOW_SWEEP_AT_PATH, str(now))
    try:
        cfg = load_config()
        ts = str(int(time.time() * 1000))
        nonce = py_secrets.token_hex(16)
        sig = hmac.new(
            cfg["nodeSecret"].encode("utf-8"),
            f'{cfg["nodeId"]}:{ts}:{nonce}:workflow_sweep'.encode("utf-8"),
            hashlib.sha256,
        ).hexdigest()
        body = json.dumps({
            "action": "workflow_sweep", "nodeId": cfg["nodeId"],
            "timestamp": ts, "nonce": nonce, "signature": sig, "params": {},
        }).encode("utf-8")
        req = urllib.request.Request(
            _WORKFLOW_URL, data=body,
            headers={"Content-Type": "application/json"}, method="POST",
        )
        with urllib.request.urlopen(req, timeout=30) as r:
            out = json.loads(r.read() or b"{}")
        stalled = out.get("stalled") or []
        if stalled:
            _log(f"workflow-sweep: {len(stalled)} run(s) → stalled: {stalled}")
    except Exception as e:  # noqa: BLE001
        _log(f"workflow-sweep: failed (next window retries): {e}")


def _run_declarative_sync(token: dict) -> None:
    """Prime the hash fields in ONE masked GET, then render every
    declarative file (TOOLS/SOUL/IDENTITY/USER/TEAM) whose hash changed.
    Shared by the slow safety-timer in the main loop and the SessionStart
    DECL_ONESHOT hook. Each step is individually resilient (swallows its own
    errors), so one bad target never aborts the rest."""
    _prime_node_fields(
        token,
        [
            "toolsHash", "soulHash", "identityHash", "userHash",
            "teamIndexHash", "inventoryCronHash", "workflowCronsHash",
            "a2aHash",
        ],
    )
    # Reflect channel state to Firestore + the one-time v1.1 migration, then
    # render the managed zone of TOOLS.md (cheap hash check; only rewrites on
    # change; failures swallowed so the file is never left half-written).
    _sync_channels_to_firestore(token)
    _migrate_tools_v11()
    _sync_tools_md_from_json(token)
    # SOUL.md / IDENTITY.md: same declarative mechanic (one-time migrate +
    # hash-rendered managed zone).
    # SOUL/IDENTITY/USER: F3b — se ESTANDARIZAN a canónico limpio (nuke capa A
    # TBrain/persona) y luego se renderizan sus zonas gestionadas. Reemplaza el
    # _md_migrate (CF strip) previo: el standardize local es más completo.
    _soul_standardize()
    _identity_standardize()
    _user_standardize()
    # SOUL: memoria(P,gated) → persona(D) → memory:priorities(D) → soul(P).
    if _has_conversation_memory():
        _md_sync_from_json(token, "memory")
    _md_sync_from_json(token, "persona")
    _md_sync_from_json(token, "memory_priorities")
    _md_sync_from_json(token, "soul")
    # IDENTITY: identity:data(D) → sub-agentes+equipo(P).
    _md_sync_from_json(token, "identity_data")
    _md_sync_from_json(token, "identity")
    # USER: perfil del dueño (position=start).
    _md_sync_from_json(token, "user")
    # AGENTS.md: estandariza (one-time) + 4 zonas agents:* P + tnode:security(P)
    # + tnode:guardrails(D). F3b Ola 1 + F3.5.
    _agents_standardize()
    for _ag in _AGENTS_ORDER:
        _md_sync_from_json(token, _ag)
    _md_sync_from_json(token, "security")
    _md_sync_from_json(token, "guardrails")
    # TEAM_INDEX.md: peer roster (dedicated file, hash-rendered; gone if no peers).
    _team_index_sync_from_json(token)
    # Cron declarativo del resurtido (hash-gated; rm+add vía CLI del core).
    _sync_inventory_cron(token)
    # TNode Workflows: crons declarativos (hash-gated) + barrido stalled
    # (throttled 30 min — colgado de aquí, sin timer propio).
    _sync_workflow_crons(token)
    _workflow_sweep_maybe()
    # A2A: config declarativa del plugin tnode-a2a (hash-gated; solo si el
    # plugin esta instalado en el nodo).
    # F7c: absorber clientes vendidos por checkout ANTES de materializar —
    # así el mismo pase puede cerrar la cadena si la CF ya recompuso.
    try:
        _absorb_a2a_pending_clients(token)
    except Exception as e:  # noqa: BLE001
        _log(f"a2a pending absorb (decl): {e}")
    _sync_a2a(token)
    # A2A: bloque "servicios anunciados" en el TOOLS.md del agente destino —
    # local (lee la config YA materializada), corre cada pase, idempotente.
    _sync_a2a_workspace_block()
    # Auth v2: identidad de RED del nodo (auto-provisión, opción A).
    try:
        _sync_network_identity(token)
    except Exception as e:  # noqa: BLE001
        _log(f"net identity (decl): {e}")
    # Guest workspace SOUL.md: render the owner's Business Profile so the guest
    # agent knows the business it represents (needs the token to read the
    # node-scoped config/businessProfile doc).
    _biz_profile = _firestore_get_business_profile(token)
    _ensure_guest_business_section(token, _biz_profile)
    _ensure_recepcion_business_section(_biz_profile)
    _clear_node_fields_cache()


def run_decl_oneshot() -> int:
    """Refresh the declarative files from Firestore once, then exit. Wired as an
    OpenClaw SessionStart hook so the workspace is current the moment a user
    opens a session — replacing the background poll, so reads scale with real
    usage (an idle node reads nothing). Primes all five hashes in ONE read; only
    rewrites the files whose hash changed.

    ALWAYS returns 0: a SessionStart hook must never block the session. Any
    failure (token mint, network) just leaves the existing files in place — the
    slow safety-timer and the next session-start catch up."""
    try:
        cfg = load_config()
        token = mint_token(cfg)
        if os.environ.get("TNODE_TEAM_SHADOW_ONLY"):
            # F1 cutover: solo corre el gate de paridad del compositor on-node
            # contra la CF. No renderiza ni toca ningún archivo.
            _team_shadow_check(token)
            return 0
        _md_sh = os.environ.get("TNODE_MD_SHADOW_ONLY")
        if _md_sh:
            # F3 cutover: gate de paridad de SOUL/IDENTITY (lista de targets).
            for _t in _md_sh.split(","):
                _md_shadow_check(token, _t.strip())
            return 0
        if os.environ.get("TNODE_AGENTS_DRYRUN"):
            # F3b: simula la estandarización de AGENTS.md (compone + diffea),
            # sin escribir nada. Para revisar before/after antes del rollout.
            _agents_dryrun()
            return 0
        _run_declarative_sync(token)
        _log("decl-oneshot: declarative refresh complete")
    except Exception as e:  # noqa: BLE001
        _log(f"decl-oneshot failed (non-fatal): {e}")
    return 0


def run_oneshot() -> int:
    """Push a single openclaw.json snapshot and exit.

    Used by the OS file-watcher: when openclaw.json changes, the watcher
    triggers `python3 tnode_config_sync.py` with TNODE_CONFIG_SYNC_ONESHOT=1 so the
    snapshot is reflected to Firestore immediately (no 15s latency).
    """
    try:
        cfg = load_config()
        token = mint_token(cfg)
        state = push_openclaw_config(token)
        _log(f"oneshot push ok — modelMode={state.get('modelMode')}")
        return 0
    except Exception as e:  # noqa: BLE001
        _log(f"oneshot failed: {e}")
        return 1


# La baja elimina archivos, skills y permisos ya identificados. El instalador
# tolera ausencias al repetir. Altas, hooks y llamadas externas requieren una
# revisión propia antes de permitir que se repitan con resultado incierto.
_REPLAYABLE_INTERRUPTED_COMMANDS = frozenset({"uninstall_tplugin_agent", "set_rest_credential"})


def _command_journal(token: dict) -> Path:
    scope = json.dumps([PROJECT_ID, token["uid"], token["nodeId"]]).encode()
    return OPENCLAW_DIR / f".tnode-config-sync-command-{hashlib.sha256(scope).hexdigest()}.json"


def _write_command_journal(path: Path, record: dict) -> None:
    # Los resultados pueden incluir datos de la operación. Escribir en un
    # temporal privado y sustituir el registro completo antes de continuar.
    with tempfile.NamedTemporaryFile(mode="w", encoding="utf-8", dir=path.parent, delete=False) as f:
        staged = Path(f.name)
        try:
            json.dump(record, f, default=str)
            f.flush()
            os.fsync(f.fileno())
            os.replace(staged, path)
        finally:
            staged.unlink(missing_ok=True)


def _command_outcome(token: dict, cmd: dict) -> dict:
    _log(f"handling cmd {cmd['id']} type={cmd['type']}")
    try:
        return handle_command(token, cmd)
    except urllib.error.HTTPError as error:
        if error.code == 401:
            raise  # el caller refresca el token; se conserva el registro
        _log(f"cmd {cmd['id']} HTTP error: {error.code} {error.reason}")
        return {"status": "error", "result": {"error": f"http_{error.code}"}}
    except Exception as error:  # noqa: BLE001
        _log(f"cmd {cmd['id']} error: {error}")
        return {"status": "error", "result": {"error": str(error)[:500]}}


def _process_command_record(token: dict, path: Path, record: dict, cmd: dict | None) -> bool:
    """Solo se llama bajo el bloqueo de la cola. Devuelve si publicó un resultado."""
    marker = {"configSyncAttempt": record["attempt"]}
    phase = record["phase"]
    if (
        cmd and cmd["status"] == "pending" and phase == "claiming"
        and cmd["updateTime"] == record["pendingUpdateTime"]
    ):
        updated = update_command(token, cmd, {"status": "running", "result": marker})
        if updated is None:
            # Otro escritor pudo ganar, o aterrizó el PATCH anterior. Releer
            # en el siguiente drenado antes de quitar la marca del registro.
            return False
        cmd = {**cmd, "status": "running", "result": marker, "updateTime": updated}
    if not cmd or cmd["status"] != "running" or cmd["result"] != marker:
        path.unlink()
        return False

    if phase != "finished":
        if phase == "started" and (record["replayed"] or cmd["type"] not in _REPLAYABLE_INTERRUPTED_COMMANDS):
            outcome = {"status": "error", "result": {"error": "command_outcome_unknown", "retryable": False}}
        else:
            if phase == "started":
                record["replayed"] = True
                _log(f"cmd {cmd['id']} retry after interrupted config-sync")
            record["phase"] = "started"
            _write_command_journal(path, record)
            outcome = _command_outcome(token, cmd)
        record["phase"] = "finished"
        record["patch"] = {
            "status": outcome.get("status", "done"),
            "result": outcome.get("result") or {},
            "completedAt": int(time.time() * 1000),
        }
        _write_command_journal(path, record)

    patch = record["patch"]
    if update_command(token, cmd, patch) is None:
        return False  # conservar el resultado hasta releer la versión del doc
    path.unlink()
    _log(f"cmd {cmd['id']} -> {patch['status']}")
    return True


def _drain_commands(token: dict) -> int:
    """El daemon y el wake comparten un bloqueo local, liberado al salir o morir."""
    lock_path = OPENCLAW_DIR / ".tnode-config-sync-commands.lock"
    with lock_path.open("a") as lock:
        try:
            fcntl.flock(lock.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            return 0

        path = _command_journal(token)
        processed = 0
        if path.exists():
            record = json.loads(path.read_text(encoding="utf-8"))
            cmd = _read_command(token, record["cmdId"])
            processed += _process_command_record(token, path, record, cmd)
            if path.exists():
                return processed

        for cmd in query_pending_commands(token):
            record = {
                "cmdId": cmd["id"], "attempt": py_secrets.token_hex(16),
                "phase": "claiming", "pendingUpdateTime": cmd["updateTime"], "replayed": False,
            }
            _write_command_journal(path, record)
            processed += _process_command_record(token, path, record, cmd)
            if path.exists():
                break
        return processed


def run_command_drain_oneshot() -> int:
    """Drena la cola de commands UNA vez y sale — camino PRIMARIO, disparado por
    el WAKE del app (Dashboard→Chat) vía el file-watcher .path. Sin polling."""
    try:
        cfg = load_config()
        token = mint_token(cfg)
        # Un .wake que cae durante el drain no re-dispara la unit: repetir hasta
        # vaciar la cola (acotado; el backstop de 300 s cubre el resto).
        n = 0
        for _ in range(4):
            got = _drain_commands(token)
            n += got
            if got == 0:
                break
        # F7c (1.81.0): el plugin toca .wake al canjear un claim de checkout —
        # absorbe aquí los clientes vendidos para no esperar el tick idle de
        # 300s del daemon (el claim de tobal 2026-08-30 le perdió por 19s al
        # decl pass). Mismo patrón que el loop: deja recomponer a la CF y jala.
        try:
            if _absorb_a2a_pending_clients(token) > 0:
                time.sleep(6)
                _sync_a2a(token)
        except Exception as e:  # noqa: BLE001
            _log(f"a2a pending absorb (drain): {e}")
        _log(f"drain-oneshot: processed {n} command(s)")
        return 0
    except Exception as e:  # noqa: BLE001
        _log(f"drain-oneshot failed: {e}")
        return 1


def _guest_agent_present() -> bool:
    """True if the `guest` agent entry is already in openclaw.json.

    Lee el roster via _roster_load (vista train-aware): en 2.0 nativo el
    roster vive en `agents.entries` (dict) y `agents.list` NO existe — el
    read legacy devolvía False SIEMPRE y _run_startup_self_heal reintentaba
    en loop infinito cada ~3s desde el nacimiento del nodo (cazado en HEB
    2026-09-02: 19k retries en 16h; el unificador de 1.87 cubrió los 4
    writers pero este reader se le escapó)."""
    try:
        cfg = json.loads(OPENCLAW_JSON_PATH.read_text())
    except Exception:  # noqa: BLE001
        return False
    agents_list = _roster_load(cfg.get("agents", {}) or {})
    return any(
        isinstance(a, dict) and a.get("id") == "guest" for a in agents_list
    )


def _ensure_sync_json_env_fields() -> None:
    """Backfill projectId/webApiKey en tnode-chat-sync.json desde el env.

    Los plugins del gateway (context-engine / tnode-channel / tnode-transport)
    leen ese json para autenticarse; sin estos campos caían a sus fallbacks
    de PROD, que en nodos beta producían CREDENTIAL_MISMATCH y lecturas al
    Firestore equivocado (cazado 2026-07-14 con el primer Agente Negocio).
    Los plugins 0.13.0+ también derivan el entorno del mintUrl — esto es
    cinturón y tirantes, y deja el entorno explícito para debugging.
    Idempotente: no toca campos ya presentes.
    """
    try:
        path = OPENCLAW_DIR / "tnode-chat-sync.json"
        if not path.exists():
            return
        data = json.loads(path.read_text())
        changed = False
        pid = os.environ.get("TNODE_PROJECT_ID")
        key = os.environ.get("TNODE_FIREBASE_WEB_API_KEY")
        if pid and not data.get("projectId"):
            data["projectId"] = pid
            changed = True
        if key and not data.get("webApiKey"):
            data["webApiKey"] = key
            changed = True
        if changed:
            path.write_text(json.dumps(data, indent=2) + "\n")
            _log(
                "sync json: backfilled env fields "
                f"(projectId={bool(pid)}, webApiKey={bool(key)})"
            )
    except Exception as e:  # noqa: BLE001 — best-effort, nunca frena el boot
        _log(f"sync json backfill failed: {e}")


def _migrate_plaintext_secrets_v2() -> None:
    """F2 Credential Management: migra credenciales plaintext existentes en
    openclaw.json al shared secret store + SecretRef (solo train 2.0).

    Alcance deliberado (superficie soportada por el SDK que nosotros
    poblamos): models.providers.*.apiKey · channels.telegram.botToken ·
    plugins.entries.brave.config.webSearch.apiKey. gateway.auth.token NO
    (chat-sync lee ese valor; store secrets son write-only). Idempotente:
    un campo ya-ref se salta; sin cambios no escribe nada."""
    if not _openclaw_is_v2():
        return
    cfg = read_openclaw_json()
    if not isinstance(cfg, dict):
        return
    migrated: list[str] = []

    def _to_ref(holder: dict, field: str, store_name: str, label: str) -> None:
        v = holder.get(field)
        if not isinstance(v, str):
            return  # ausente o ya-ref
        s = v.strip()
        if not s or s == "not-needed":
            return
        if _store_secret(store_name, s):
            holder[field] = _secret_ref(store_name)
            migrated.append(label)

    provs = (cfg.get("models") or {}).get("providers") or {}
    for pname, prov in provs.items():
        if isinstance(prov, dict):
            _to_ref(prov, "apiKey", _secret_store_name(pname),
                    f"models.providers.{pname}.apiKey")
    tg = (cfg.get("channels") or {}).get("telegram")
    if isinstance(tg, dict):
        _to_ref(tg, "botToken", "TELEGRAM_BOT_TOKEN", "channels.telegram.botToken")
    brave_ws = ((((cfg.get("plugins") or {}).get("entries") or {})
                 .get("brave") or {}).get("config") or {}).get("webSearch")
    if isinstance(brave_ws, dict):
        _to_ref(brave_ws, "apiKey", "BRAVE_API_KEY",
                "plugins.entries.brave.config.webSearch.apiKey")

    if migrated:
        _write_openclaw_json(cfg)
        _secrets_reload()
        _log(f"secrets: migrados a SecretRef store: {', '.join(migrated)}")


def _run_startup_self_heal() -> bool:
    """Run the idempotent startup self-heal (agents index, workspace dirs,
    skills, guest agent).

    Returns True when nothing more should be attempted (success, or a
    non-retryable error already logged). Returns False ONLY on the snapshot
    boot race: the daemon (user `tnode`) started before the installer chowned
    openclaw.json to `tnode`, so the agents.list write isn't possible yet —
    signalling main() to retry on the next loop tick until it lands, so a
    freshly-provisioned node materializes the `guest` agent (Opción B) without
    a manual config-sync restart."""
    try:
        _regenerate_agents_index()
        _ensure_workspace_dirs()
        _ensure_workspace_skills()
        _ensure_platform_agents()
        _ensure_a2a_agents_self_heal()
        _ensure_guest_agent()
        _ensure_heartbeat_default()
        _ensure_gateway_policy_floor()
        _migrate_plaintext_secrets_v2()
    except PermissionError as e:
        _log(f"self-heal deferred (boot race, will retry): {e}")
        return False
    except Exception as e:  # noqa: BLE001
        _log(f"startup self-heal failed: {e}")
        return True
    # Confirm the guest entry actually landed. If openclaw.json wasn't readable
    # or present yet (boot race), the ensure was a silent no-op — keep retrying.
    if _guest_agent_present():
        return True
    _log("self-heal: guest agent not present yet (openclaw.json not ready) — will retry")
    return False


def main() -> int:
    if DECL_ONESHOT:
        return run_decl_oneshot()
    if ONESHOT:
        return run_oneshot()
    if DRAIN_ONESHOT:
        return run_command_drain_oneshot()

    try:
        cfg = load_config()
    except Exception as e:  # noqa: BLE001
        _log(f"config error: {e}")
        return 2

    _log(f"starting tnode-config-sync for nodeId={cfg['nodeId']}")
    # Self-heal: regenerate AGENTS_INDEX.md and ensure the workspace
    # references survive workspace drift (e.g. user wiped SOUL.md
    # manually, or the node was provisioned before v1.4.0). Best-effort
    # — failures here are logged but don't prevent the daemon loop. On a
    # snapshot-provisioned node this races the installer's chown of
    # openclaw.json (see _run_startup_self_heal); main() retries in the loop
    # below until the guest agent (Opción B) materializes — no manual restart.
    self_heal_done = _run_startup_self_heal()
    # Backfill env fields (projectId/webApiKey) into tnode-chat-sync.json so
    # the gateway plugins never fall back to their baked PROD credentials on
    # a beta node (CREDENTIAL_MISMATCH — incidente 2026-07-14).
    _ensure_sync_json_env_fields()
    # Reflect a hand-configured Telegram channel (openclaw.json) into
    # channels-state.json so the mobile widget shows it without a re-link.
    _derive_telegram_state_if_missing()
    _daemon_started_at = time.time()
    token: dict | None = None
    backoff = 1.0
    empty_polls = 0
    decl_bootstrap_done = False  # one-time declarative refresh on daemon startup

    # Push initial state on startup so Firestore reflects current openclaw.json
    # even if the file hasn't changed since last boot.
    startup_pushed = False
    # 2.12.0: un nodo que trae el esquema previo al renombre se migra a
    # tbrain-models UNA vez por arranque (re-jala su key existente, no mintea).
    models_migration_checked = False
    _last_fleet_report: float | None = None

    while True:
        try:
            now = int(time.time())
            # Boot-race backstop: if the startup self-heal couldn't write
            # openclaw.json yet (daemon started before the installer's chown),
            # keep retrying every tick until the guest agent lands.
            if not self_heal_done:
                self_heal_done = _run_startup_self_heal()
                if self_heal_done:
                    _log("startup self-heal completed on loop retry (boot race cleared)")
            if token is None or now >= token["expiresAt"]:
                token = mint_token(cfg)
                _log(f"minted token for uid={token['uid']} node={token['nodeId']}")
                backoff = 1.0

            if not startup_pushed:
                try:
                    state = push_openclaw_config(token)
                    _log(f"startup push ok — modelMode={state.get('modelMode')}")
                    startup_pushed = True
                except urllib.error.HTTPError as e:
                    if e.code == 401:
                        token = None
                        continue
                    _log(f"startup push failed: {e.code} {e.reason}")

            if startup_pushed and not models_migration_checked:
                models_migration_checked = True
                try:
                    if _needs_models_migration(read_openclaw_json() or {}):
                        _log("models: esquema previo detectado — migrando a "
                             f"{MODELS_PROVIDER}")
                        r = handle_apply_model_key(token, {})
                        _log(f"models: migración → {r.get('status')} "
                             f"{json.dumps(r.get('result'))[:300]}")
                except Exception as e:  # noqa: BLE001 — se reintenta al reiniciar
                    _log(f"models: migración falló (no fatal): {e}")

            # F7c: clientes vendidos por checkout (pending file del plugin) →
            # Firestore en cada tick (check barato de archivo; la lista de
            # gracia del plugin cubre el lag hasta que la cadena declarativa
            # los materializa).
            try:
                if _absorb_a2a_pending_clients(token) > 0:
                    time.sleep(6)  # deja recomponer a la CF antes del pull
                    _sync_a2a(token)
            except Exception as e:  # noqa: BLE001
                _log(f"a2a pending absorb: {e}")

            # 2.10.1: un agente recién ligado a un canal externo (grupo o
            # contacto de terceros) recibe la allowlist sin esperar reinicio.
            try:
                _enforce_client_agents_tools_if_changed()
            except Exception as e:  # noqa: BLE001
                _log(f"client-tools tick: {e}")

            # Inventario de flota: al arrancar y luego cada FLEET_REPORT_EVERY_S
            # (24h por defecto). Al arrancar porque un nodo que vuelve de estar
            # apagado debe reflejarse enseguida; el timer porque la consola tiene
            # que envejecer poco. Best-effort: un fallo aqui NUNCA debe frenar el
            # drenado de comandos, que es la funcion primaria del daemon.
            if (_last_fleet_report is None
                    or (time.time() - _last_fleet_report) >= FLEET_REPORT_EVERY_S):
                try:
                    if report_fleet_inventory(token):
                        _last_fleet_report = time.time()
                    else:
                        # Sin health-check.py no se reintenta cada tick.
                        _last_fleet_report = time.time()
                except urllib.error.HTTPError as e:
                    if e.code == 401:
                        token = None
                        continue
                    _log(f"fleet: reporte fallido: {e.code} {e.reason}")
                    _last_fleet_report = time.time()
                except Exception as e:  # noqa: BLE001
                    _log(f"fleet: reporte fallido: {e}")
                    _last_fleet_report = time.time()

            # Drena la cola (BACKSTOP). El camino primario es el WAKE: el app
            # dispara el drain-oneshot (DRAIN_ONESHOT) al pasar Dashboard→Chat.
            # Aquí solo barremos cada POLL_IDLE_S (300s) por si se perdió un wake.
            try:
                n_processed = _drain_commands(token)
            except urllib.error.HTTPError as e:
                if e.code == 401:
                    token = None
                    continue
                raise
            empty_polls = 0 if n_processed else empty_polls + 1

            # Declarative .md refresh is event-driven (NO periodic poll): on a
            # new session, tnode-chat-sync spawns this daemon with
            # DECL_ONESHOT=1. We only refresh ONCE here, on startup, so the
            # files are current right after a reboot/restart even before the
            # first session arrives.
            if not decl_bootstrap_done:
                _run_declarative_sync(token)
                decl_bootstrap_done = True

            # Stay on the active cadence while the self-heal is still pending
            # so a snapshot-provisioned node materializes the guest agent
            # quickly once openclaw.json becomes writable (boot-race fix).
            # Dentro de la ventana post-boot NUNCA caemos al idle de 300s:
            # el wake del app se pierde si llega mientras el gateway sigue
            # arrancando, y el primer apply_model_key de un nodo fresco
            # no puede esperar 5 minutos (incidente 2026-07-14).
            if not self_heal_done or empty_polls < IDLE_AFTER:
                interval = POLL_ACTIVE_S
            elif (time.time() - _daemon_started_at) < BOOT_FAST_WINDOW_S:
                interval = BOOT_FAST_POLL_S
            else:
                interval = POLL_IDLE_S
            time.sleep(interval)
        except KeyboardInterrupt:
            return 0
        except urllib.error.HTTPError as e:
            if e.code == 401:
                # Persistent 401 (e.g. clock skew, revoked node, stale
                # nodeSecret) used to spam ~10 lines/sec. Reuse the existing
                # `backoff` variable (reset to 1.0 on a successful mint at
                # the top of the loop) so we slow down without blocking
                # legitimate single-shot refreshes.
                _log(f"idToken rejected — refreshing; backoff={backoff:.1f}s")
                token = None
                time.sleep(backoff)
                backoff = min(60.0, backoff * 2)
                continue
            body = getattr(e, "server_body", "")
            _log(
                f"HTTP error: {e.code} {e.reason} body={body[:300]}; "
                f"backoff={backoff:.1f}s"
            )
            time.sleep(backoff)
            backoff = min(60.0, backoff * 2)
        except Exception as e:  # noqa: BLE001
            _log(f"loop error: {e}; backoff={backoff:.1f}s")
            time.sleep(backoff)
            backoff = min(60.0, backoff * 2)


if __name__ == "__main__":
    sys.exit(main())
CFGSYNCPYEOF
}

install_tnode_config_sync() {
    local DEST_SCRIPTS="$OPENCLAW_HOME/scripts"
    mkdir -p "$DEST_SCRIPTS" "$OPENCLAW_HOME/logs"

    write_tnode_config_sync_py "$DEST_SCRIPTS/tnode_config_sync.py"
    write_tnode_agent_model_py "$DEST_SCRIPTS/tnode_agent_model.py"
    chmod +x "$DEST_SCRIPTS/tnode_config_sync.py"
    chown -R "$TNODE_USER":"$TNODE_USER" "$OPENCLAW_HOME" 2>/dev/null || true

    success "tnode-config-sync → $DEST_SCRIPTS/tnode_config_sync.py"

    case "$OS" in
        Darwin)
            install_config_sync_launchd
            install_config_sync_launchd_watcher
            ;;
        Linux)
            install_config_sync_systemd
            install_config_sync_systemd_watcher
            install_config_sync_wake_systemd
            ;;
    esac
}

install_config_sync_launchd() {
    local plist_label="com.tbrain.tnode-config-sync"
    local plist_dest="$HOME/Library/LaunchAgents/${plist_label}.plist"

    mkdir -p "$(dirname "$plist_dest")"

    cat > "$plist_dest" <<PLIST
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
    <key>Label</key><string>${plist_label}</string>
    <key>ProgramArguments</key>
    <array>
        <string>/usr/bin/env</string>
        <string>python3</string>
        <string>${OPENCLAW_HOME}/scripts/tnode_config_sync.py</string>
    </array>
    <key>RunAtLoad</key><true/>
    <key>KeepAlive</key><true/>
    <key>StandardOutPath</key><string>${OPENCLAW_HOME}/logs/tnode-config-sync.out.log</string>
    <key>StandardErrorPath</key><string>${OPENCLAW_HOME}/logs/tnode-config-sync.err.log</string>
    <key>EnvironmentVariables</key>
    <dict>
        <key>PATH</key><string>/opt/homebrew/bin:/usr/local/bin:/usr/bin:/bin</string>
        <key>HOME</key><string>${HOME}</string>
        <key>OPENCLAW_HOME</key><string>${OPENCLAW_HOME}</string>
    </dict>
    <key>WorkingDirectory</key><string>${OPENCLAW_HOME}</string>
</dict>
</plist>
PLIST

    launchctl unload "$plist_dest" 2>/dev/null || true
    launchctl load "$plist_dest"
    success "LaunchAgent tnode-config-sync cargado"
}

